fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
pub(super) fn unit(d:RetirementDemand)->semio_framework_value::RetainedCloneStep{semio_framework_value::RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes})}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
pub(super) fn receive(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut NativeDecodeControl<'_>,RetainedCloneGrant)->Result<semio_framework_value::RetainedCloneStep,ValueError>)->Result<bool,OriginalTurnFailure>{
 if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),d){return Ok(false)}let result=cx.with_native_receiving::<_,NativeConstructionStepFailure<ValueError>>(|native|native.receive_construction_step(d,run));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let reconciled=cx.receiving_issued_grant().map(|grant|cx.consume_receiving_retained(grant,p)).transpose();cx.consume_fuel(p.copied_items as u64);match(result,reconciled){(Ok(_),Ok(_))=>Ok(true),(Err(error),Ok(_))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=Some(receipt);Err(failure)}}
}
impl OriginalManifestMetadata{
 pub fn admit(view:Option<&mut Vec<u8>>,mut limits:store::os_pack::PackLimits,cx:&mut StepContext<'_>,slot:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{
  if slot.is_some(){return Err(refusal("original metadata destination is occupied"))}let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let maximum=usize::try_from(limits.max_total_alloc).map_err(|_|refusal("original metadata allocation limit exceeds target"))?;
  admit_original_construction(cx,slot,construction(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original metadata requires its actual decoder recipient"))?);let mut failure=None;let parser=if let Some(bytes)=view.filter(|bytes|!bytes.is_empty()){limits.max_file_len=bytes.len()as u64;match RetainedIntrinsicBody::new(RetainedIntrinsicInput::OwnedBytes(std::mem::take(bytes)),limits,maximum){Ok(parser)=>Some(parser),Err((original,RetainedIntrinsicInput::OwnedBytes(original_bytes)))=>{*bytes=original_bytes;failure=Some(OriginalCommandPackFailure{original});None},Err(_)=>unreachable!()}}else{None};let phase=if parser.is_some(){0}else{8};Ok((Box::new(Self{binding,decoder,parser:ManuallyDrop::new(parser),failure:ManuallyDrop::new(failure),parsed:ManuallyDrop::new(None),source:ManuallyDrop::new(None),receiver:ManuallyDrop::new(None),view:ManuallyDrop::new(None),actor:ManuallyDrop::new(None),meta:ManuallyDrop::new(None),retirement:Default::default(),actor_source:None,offset:0,phase,closing:false}),unit(d).progress()))})
 }
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(refusal("original metadata requires its exact caller and decoder"))}Ok(())}
 pub fn ready(&self)->bool{!self.closing&&self.phase==11}
 pub fn advance(&mut self,actor:&str,instance_id:u32,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.closing{return Err(refusal("original metadata is closing"))}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original metadata receiving cancelled").into())}if self.failure.is_some(){return match semio_framework_job::admit_original_domain_failure(&mut self.failure,cx)?{Some(error)=>Err(error),None=>Ok(false)}}if self.ready(){return Ok(true)}let body=cx.retained_grant().maximum_copy_bytes;
  match self.phase{
   0=>{let parser=self.parser.as_mut().unwrap();let call=parser.advance_original_step(cx.retained_grant(),cx.is_cancelled());cx.consume_retained(call.progress)?;cx.consume_fuel(call.progress.copied_items as u64);match call.result{Err(original)=>*self.failure=Some(OriginalCommandPackFailure{original}),Ok(step)if step.complete=>self.phase=1,_=>{}}},
   1=>{if paid(cx,size_of::<DslValue>())?{*self.parsed=self.parser.as_mut().unwrap().take_output();self.phase=2}},
   2=>{let birth=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,release_bytes:0};let g=cx.retained_grant();if admit_original_construction(cx,&mut self.source,construction(d),|_|{let original=self.parsed.take().unwrap();match RetainedCloneSource::admit_owned(original,(),g){Ok(v)=>Ok(v),Err((error,original,()))=>{*self.parsed=Some(original);Err(error)}}})?{self.phase=3}},
   3=>{let d=NativeReceivingOriginal::<DslValue,ViewModel>::shell_demand();if paid(cx,d.copy_bytes)?{let(owner,_)=NativeReceivingOriginal::begin_shell(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()})?;*self.receiver=Some(owner);self.phase=4}},
   4=>{let d=self.receiver.as_ref().unwrap().original_capture_demand()?;let g=cx.retained_grant();if retained_clone_grant_admits(g,d)&&paid(cx,d.copy_bytes)?{self.receiver.as_mut().unwrap().admit_original(&mut self.source,g)?;self.phase=5}},
   5=>{let d=self.receiver.as_ref().unwrap().receiver_birth_demand()?;if receive(cx,d,|control,g|{control.charge(d.capacity_bytes)?;self.receiver.as_mut().unwrap().begin_receiver(g).map(semio_framework_value::RetainedCloneStep::Progress)})?{self.phase=6}},
   6=>{let d=self.receiver.as_ref().unwrap().demands(body)?;receive(cx,d,|control,g|self.receiver.as_mut().unwrap().advance(control,body,g))?;if self.receiver.as_ref().unwrap().output_ready(){self.phase=7}},
   7=>{let d=self.receiver.as_ref().unwrap().take_demand()?;let g=cx.retained_grant();if retained_clone_grant_admits(g,d)&&paid(cx,d.copy_bytes)?{*self.view=Some(self.receiver.as_mut().unwrap().take(g)?.ok_or_else(||refusal("original metadata typed view disappeared"))?.0);self.receiver.as_mut().unwrap().begin_close();self.phase=8}},
   8=>{let d=RetirementDemand{capacity_bytes:actor.len(),..header::<String>()};let source=(actor.as_ptr()as usize,actor.len());if receive(cx,d,|control,_|{control.charge(d.capacity_bytes)?;*self.actor=Some(String::with_capacity(actor.len()));self.actor_source=Some(source);self.phase=9;Ok(unit(d))})?{}},
   9=>{if self.actor_source!=Some((actor.as_ptr()as usize,actor.len())){return Err(refusal("original metadata actor authority changed"))}let mut end=(self.offset+64).min(actor.len());while !actor.is_char_boundary(end){end-=1}let copied=end-self.offset;if paid(cx,copied+size_of::<usize>())?{self.actor.as_mut().unwrap().push_str(&actor[self.offset..end]);self.offset=end;if end==actor.len(){self.phase=10}}},
   10=>{let mut d=SharedUtf8::admission_demand();d.copy_bytes=2*size_of::<ActionMeta>()+size_of::<String>();if receive(cx,d,|control,g|{control.charge(d.capacity_bytes)?;let text=self.actor.take().unwrap();let(shared,_)=SharedUtf8::admit(text,g).unwrap_or_else(|_|unreachable!());*self.meta=Some(ActionMeta{actor:shared,instance_id,view_state:self.view.take()});self.phase=11;Ok(unit(d))})?{}},_=>return Err(refusal("original metadata receiving phase is invalid"))
  }Ok(self.ready())
 }
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;self.closing=true;if self.failure.is_some(){return match semio_framework_job::admit_original_domain_failure(&mut self.failure,cx)?{Some(error)=>Err(error),None=>Ok(false)}}let body=cx.retained_grant().maximum_copy_bytes;
  if let Some(parser)=self.parser.as_mut(){if !parser.terminal_is_empty(){let call=parser.close_original_step(cx.retained_grant());cx.consume_retained(call.progress)?;cx.consume_fuel(call.progress.copied_items as u64);if let Err(original)=call.result{*self.failure=Some(OriginalCommandPackFailure{original})}return Ok(false)}if paid(cx,size_of::<usize>())?{self.parser.take();}return Ok(false)}
  if let Some(receiver)=self.receiver.as_mut(){receiver.begin_close();if !receiver.terminal_is_empty(){let d=receiver.close_demands(body)?;semio_framework_job::close_original_retained_step(cx,d,|g|receiver.close_step(g))?;return Ok(false)}if paid(cx,size_of::<usize>())?{self.receiver.take();}return Ok(false)}
  if !self.retirement.is_empty(){let mut selected=self.retirement.select(body)?;let d=selected.demands();semio_framework_job::close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}
  macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.$field,g)?.unwrap_or(semio_framework_value::RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}}}close!(parsed,DslValue);close!(source,RetainedCloneSource<DslValue>);close!(view,ViewModel);close!(actor,String);close!(meta,ActionMeta);Ok(true)
 }
 pub fn terminal_is_empty(&self)->bool{self.parser.is_none()&&self.failure.is_none()&&self.parsed.is_none()&&self.source.is_none()&&self.receiver.is_none()&&self.view.is_none()&&self.actor.is_none()&&self.meta.is_none()&&self.retirement.is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalManifestMetadata{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original metadata requires complete paid closure")}}
